```yaml
name: Community PR Permissions Check

on:
  pull_request_target:
    types: [opened, synchronize, reopened]

jobs:
  check-community-pr:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      contents: read
    steps:
      - name: Verify PR author permissions
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const author = pr.user.login;
            // Check if the author is a member of the organization
            let isOrgMember = false;
            try {
              await github.rest.orgs.getMembershipForUser({
                org: context.repo.owner,
                username: author
              });
              isOrgMember = true;
            } catch (e) {
              if (e.status !== 404) throw e;
            }
            // Check if the author has write access to the repository
            const { data: repo } = await github.rest.repos.get({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            const hasWriteAccess = repo.permissions?.push;
            if (!isOrgMember && !hasWriteAccess) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: `Hi @${author}, this PR is from a community contributor. Please ensure you have the necessary permissions or contact the maintainers.`
              });
              throw new Error('Community contributor does not have write access to the repository.');
            }
